INSERT INTO `employee` VALUES (1,1,1,0,45,0,'Mahendra sahu','8874752747',1,'mahendra.s@neuralinfo.org','25d55ad283aa400af464c76d713c07ad',1,'2025-06-03 09:09:23','2022-08-25 09:26:39',''),(37,4,3,1,0,0,'Saptarshi Hazre','9681454123',1,'saptarshi.hazra@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',2,'2024-11-18 13:24:10','0000-00-00 00:00:00','1731936250Saptarshi--East.png'),(38,4,4,1,0,0,'Rubina Haque','9433302609',2,'rubina.haque@crymail.org','d183ad0f91e96c4febb555e50795d00a',1,'2025-06-05 05:11:04','0000-00-00 00:00:00','1722240694Rubina.png'),(39,4,3,3,0,0,'Pallavi Yedekar','9960671355',2,'pallavi.yedekar@crymail.org','894a5af897b206775e55187b0edbf404',1,'2025-03-28 06:29:19','0000-00-00 00:00:00','17431433591720096853Pallavi-Y.png'),(40,4,4,3,0,0,'Renita Lopes','7030195220',2,'renita.lopes@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2024-11-18 13:10:22','0000-00-00 00:00:00','1731935422Renita_West.png'),(41,4,5,4,0,0,'Shreeya Dutta','8724070227',2,'shreeya.dutta@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2024-11-18 13:10:07','0000-00-00 00:00:00','1731935407shreeya-signature.png'),(42,4,6,4,0,0,'Smriti Rustagi','987390936',2,'smriti.rustagi@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-03-06 10:13:59','0000-00-00 00:00:00','17412560391729167254Smriti--North-signature.png'),(43,4,5,2,0,0,'Manoj Thapa','8792144057',1,'manoj.thapa@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2024-11-18 13:11:44','0000-00-00 00:00:00','1731935504Manoj-South.png'),(44,4,6,2,0,0,'Monisha Muruli','9686112976',2,'monisha.murali@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2024-11-18 13:08:53','0000-00-00 00:00:00','1731935333Monisha.png'),(45,1,1,0,0,0,'Anupama Muhuri','7093174666',2,'anupama.muhuri@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-04-01 10:32:10','0000-00-00 00:00:00','1720156740Anupamas-signature--Head-Office.png'),(46,1,3,0,0,0,'Bitapi Baruah','9990309659',2,'bitapi.baruah@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-04-01 10:32:10','0000-00-00 00:00:00',''),(47,1,5,0,0,0,'Vishal Patil','9637747311',1,'vishal.patil@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-04-01 10:32:10','0000-00-00 00:00:00',''),(48,1,7,0,0,0,'Iswarya S','8682001951',2,'iswarya.s@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-04-01 10:32:10','0000-00-00 00:00:00',''),(49,4,3,1,0,0,'Saumya Gupta','9810795996',2,'saumya.gupta@crymail.org','827ccb0eea8a706c4c34a16891f84e7b',1,'2025-03-10 05:51:29','0000-00-00 00:00:00','17415858891731936399signature.png'),(50,4,2,2,0,0,'Mahendra Sahu','4521254123',1,'mahendrasahu421422@gmail.com','6dc26d3922df2116175757c4a4e15de4',1,'2025-07-07 11:28:08','0000-00-00 00:00:00','17518876881720156740Anupamas-signature--Head-Office.png');
