--
-- Table structure for table `feedback`
--

DROP TABLE IF EXISTS `feedback`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `feedback` (
  `feedback_id` int(11) NOT NULL AUTO_INCREMENT,
  `intern_id` int(11) NOT NULL,
  `pre_internship_correspondence` int(2) NOT NULL,
  `selection_process` int(2) NOT NULL,
  `orientation_beginning` int(2) NOT NULL,
  `defined_goals` int(2) NOT NULL,
  `assignment_planning` int(2) NOT NULL,
  `constructive_feedback` int(2) NOT NULL,
  `needed_support` int(2) NOT NULL,
  `appropriate_and_sufficient` int(2) NOT NULL,
  `work_flow` int(2) NOT NULL,
  `encouraging` int(2) NOT NULL,
  `stimulating` int(2) NOT NULL,
  `contributed_cry_work` int(2) NOT NULL,
  `increased_conceptual_learning` int(2) NOT NULL,
  `another_student` int(2) NOT NULL,
  `continue_partner` varchar(255) NOT NULL,
  `internship_with_cry_again` int(2) NOT NULL COMMENT '1 for yes 2 for no 3 for may be',
  `overall_internship` varchar(255) NOT NULL,
  `overall_experience` varchar(255) NOT NULL,
  `any_suggestions` varchar(255) NOT NULL,
  `creation_date` date NOT NULL,
  `modification_date` date NOT NULL,
  `status` int(2) NOT NULL,
  PRIMARY KEY (`feedback_id`)
) ENGINE=InnoDB AUTO_INCREMENT=181 DEFAULT CHARSET=utf8mb4;
/*!40101 SET character_set_client = @saved_cs_client */;

