DROP TABLE IF EXISTS `interntask`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `interntask` (
  `intern_task_id` int(10) NOT NULL AUTO_INCREMENT,
  `region_id` int(10) DEFAULT NULL,
  `city_id` int(11) DEFAULT NULL,
  `task_type_id` int(11) DEFAULT NULL,
  `task_for` int(2) NOT NULL COMMENT '1 for volunteer 2 for intern',
  `task_title` varchar(255) NOT NULL,
  `task_description` text NOT NULL,
  `task_brief` longtext NOT NULL,
  `start_date` date NOT NULL,
  `expected_end_date` date DEFAULT NULL COMMENT 'Expected end date of task',
  `task_state_id` int(10) DEFAULT NULL,
  `task_city_id` int(10) DEFAULT NULL,
  `keyword` varchar(200) NOT NULL,
  `intern_required` int(10) NOT NULL,
  `task_status` int(5) NOT NULL COMMENT '0 for New, 1 for Complete',
  `modification_date` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP,
  `creation_date` date DEFAULT NULL,
  `to_do` text NOT NULL,
  `status` int(5) NOT NULL,
  PRIMARY KEY (`intern_task_id`)
) ENGINE=InnoDB AUTO_INCREMENT=70 DEFAULT CHARSET=latin1;
/*!40101 SET character_set_client = @saved_cs_client */;

